import java.util.Scanner;

public class Main {
    static int n, k, mod;
    static long[] factorials;
    static long[] inverses;
    static long[][] memo;

    static int getLowbit(int x) {
        return x & (-x);
    }

    static long fastPower(long base, int exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static void initialize() {
        factorials = new long[n + 1];
        inverses = new long[n + 1];
        factorials[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorials[i] = (factorials[i - 1] * i) % mod;
        }
        inverses[n] = fastPower(factorials[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inverses[i] = (inverses[i + 1] * (i + 1)) % mod;
        }
    }

    static long recurse(int x, int s) {
        if (memo[x][s] != -1) return memo[x][s];
        if (s == 0) {
            long res = (factorials[n] * factorials[k]) % mod;
            res = (res * inverses[k - x]) % mod;
            return memo[x][s] = res;
        }
        int remaining = s - getLowbit(s);
        long total = 0;
        for (int t = remaining; t != 0; t = (t - 1) & remaining) {
            total = (total + recurse(x + 1, t) * inverses[s - t]) % mod;
        }
        total = (total + recurse(x + 1, 0) * inverses[s]) % mod;
        return memo[x][s] = total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        mod = sc.nextInt();
        initialize();
        long answer = fastPower(k, n);
        if (n % 2 == 0) {
            memo = new long[27][n + 1];
            for (int i = 0; i < 27; i++) {
                for (int j = 0; j <= n; j++) {
                    memo[i][j] = -1;
                }
            }
            answer = (answer - recurse(0, n) + mod) % mod;
        }
        System.out.println(answer);
        sc.close();
    }
}
